export const adversaryRendererStyles = ".enemy-card {\n  --ink: #1D1713;\n  --bone: #EEE4D0;\n  --oxblood: #641F1D;\n  box-sizing: border-box;\n  position: relative;\n  width: 90mm;\n  height: 142mm;\n  overflow: hidden;\n  background: var(--bone);\n  color: #1D1713;\n  font-family: \"Noto Sans SC\", sans-serif;\n  border: 0.75mm solid #21150F;\n}\n.enemy-card.is-fluid { height: auto; min-height: 142mm; overflow: visible; }\n.enemy-art { position: relative; height: 42.5mm; overflow: hidden; background: #251A14; }\n.enemy-art img { width: 100%; height: 100%; display: block; object-fit: cover; }\n.enemy-art::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 54.12%, #1D1310CC 100%); }\n.enemy-art.is-text-only::after { background: none; }\n.enemy-card.is-text .enemy-art { height: 32mm; background: #1D1310CC; }\n.enemy-card.is-text .enemy-body { height: calc(142mm - 32mm); }\n.enemy-card.is-text .enemy-kicker { top: 5mm; }\n.enemy-card.is-text .enemy-heading h1 { top: 4mm; }\n.enemy-card.is-text .enemy-heading .enemy-original-title { top: 13mm; }\n.enemy-card.is-text .enemy-heading .enemy-summary { top: 19mm; }\n.enemy-card.is-image .enemy-art { height: 100%; }\n.enemy-card.is-image .enemy-art::after { display: none; }\n.enemy-image-missing { width: 100%; height: 100%; display: grid; place-items: center; color: #F8F3EA; font: 700 4mm/1.3 \"Noto Sans SC\", sans-serif; }\n.enemy-kicker { position: absolute; z-index: 2; right: 2.175mm; top: 28.304mm; width: 20.473mm; color: #F4DFBC; font: 650 4mm/1.25 \"Noto Sans SC\", sans-serif; text-align: center; }\n.enemy-heading { position: absolute; z-index: 2; inset: 0; pointer-events: none; }\n.enemy-heading h1 { position: absolute; left: 3.5mm; right: 3.5mm; top: 27mm; margin: 0; color: #FFF4DF; font: 800 7mm/1 \"Noto Sans SC\", sans-serif; }\n.enemy-heading .enemy-original-title { position: absolute; left: 3.5mm; top: 34.5mm; margin: 0; color: #D8BA91; font: 650 2.5mm/1.25 \"Noto Sans SC\", sans-serif; }\n.enemy-heading .enemy-summary { position: absolute; left: 3.5mm; top: 38.25mm; width: 81.5mm; margin: 0; color: #dcb299; font: 500 2.375mm/1.25 \"Noto Sans SC\", sans-serif; font-style: italic; }\n.enemy-body { box-sizing: border-box; height: 99.5mm; padding: 2.5mm 2.5mm 2.5mm 2.5mm; display: flex; flex-direction: column; gap: 1.5mm; }\n.enemy-brief { height: 14.5mm; display: flex; align-items: center; gap: 1.5mm; }\n.enemy-motives { box-sizing: border-box; width: 52.5mm; height: 14.5mm; padding: 1.5mm 1.75mm; display: flex; flex-direction: column; justify-content: center; gap: 0.25mm; color: #1D1713; font: 650 2.8mm/1.3 \"Noto Sans SC\", sans-serif; background: #F7EBD6; border: 0.25mm solid #D4B78D; border-radius: 1mm; }\n.enemy-motives p { margin: 0; }\n.enemy-motives p + p { color: #641F1D; font: 650 2.7mm/1.3 \"Noto Sans SC\", sans-serif; }\n.enemy-stats { width: 31mm; height: 14.5mm; display: grid; grid-template-columns: 46fr 78fr; }\n.enemy-stat { display: grid; place-content: center; text-align: center; border: 0.25mm solid #AD8B68; }\n.enemy-stat b { font: 800 4.5mm/1.25 \"Noto Sans SC\", sans-serif; color: #641F1D; }\n.enemy-stat span { font: 650 2.25mm/1.25 \"Noto Sans SC\", sans-serif; color: #1D1713; }\n.enemy-attack { box-sizing: border-box; height: 5.063mm; display: flex; align-items: center; padding: 1.75mm 2mm; background: #641F1D; }\n.enemy-attack strong { display: block; color: #FFF0D5; font: 750 4mm/1.25 \"Noto Sans SC\", sans-serif; }\n.enemy-state { height: 15mm; display: flex; flex-direction: column; gap: 1.5mm; }\n.enemy-state-row { height: 6.5mm; display: flex; align-items: center; gap: 1mm; }\n.enemy-state-label { box-sizing: border-box; width: 14.5mm; height: 6.5mm; display: grid; place-items: center; background: #21150F; color: #F8DDBA; font: 700 2.25mm/1.25 \"Noto Sans SC\", sans-serif; }\n.enemy-state-markers { display: flex; gap: 1mm; color: #111827; }\n.enemy-state-marker { width: 6mm; height: 6mm; display: grid; place-items: center; padding: 0; border: 0; background: transparent; color: inherit; font: inherit; font-size: 6mm; line-height: 1; }\n.enemy-state-marker:not(:disabled) { cursor: pointer; }\n.enemy-state-row.is-stress { height: 6.5mm; }\n.enemy-state-row.is-stress .enemy-state-label { width: 14.5mm; height: 6.5mm; color: #F8DDBA; font: 700 2.25mm/1.25 \"Noto Sans SC\", sans-serif; }\n.enemy-state-row.is-stress .enemy-state-markers { gap: 1mm; color: #424039; }\n.enemy-state-row.is-stress .enemy-state-marker { width: 6mm; height: 6mm; font-size: 4.2mm; }\n.enemy-feature-heading { height: 4.5mm; display: flex; align-items: center; gap: 2mm; color: #641F1D; font: 800 3.25mm/1 \"Noto Sans SC\", sans-serif; }\n.enemy-feature-heading::after { content: \"\"; flex: 1; height: 0.5mm; background: #B88A57; }\n.enemy-features { height: 44mm; display: grid; grid-template-rows: 14mm 14mm 14mm; gap: 1mm; }\n.enemy-feature { box-sizing: border-box; display: grid; grid-template-columns: 19mm 60mm; align-items: start; gap: 2mm; padding: 1.5mm 2mm; overflow: hidden; background: #F7EBD6; border: 0.25mm solid #D4B78D; border-radius: 1mm; }\n.enemy-feature h2 { margin: 0; color: #641F1D; font: 800 3.5mm/1.2 \"Noto Sans SC\", sans-serif; }\n.enemy-feature h2 small { display: block; color: #5E4637; font: 650 2.125mm/1.2 \"Noto Sans SC\", sans-serif; }\n.enemy-feature h2 small span { display: block; }\n.enemy-feature p { margin: 0; color: #1D1713; font: 450 2.75mm/1.28 \"Noto Sans SC\", sans-serif; }\n.enemy-card.is-fluid .enemy-body { height: auto; }\n.enemy-card.is-fluid .enemy-features { height: auto; grid-template-rows: none; }\n.enemy-card.is-fluid .enemy-feature { min-height: 14mm; }";
